action.code:
size_t group = min_bit / bitmap_info_nbits_per_group(binfo);
size_t group_bit = min_bit % bitmap_info_nbits_per_group(binfo);
size_t ngroups = bitmap_info_ngroups(binfo);
for (; group < ngroups; group++) {
    bitmap_t word = bitmap[group];
    if (group_bit == 0 && word == 0) {
        // Entire group is unset, skip to next group
        continue;
    }
    // Mask out bits before group_bit
    word &= ~((1UL << group_bit) - 1);
    if (word != 0) {
        // Find first unset bit in this word
        size_t bit = group * bitmap_info_nbits_per_group(binfo);
        while (!(word & 1)) {
            if (bit >= bitmap_info_nbits(binfo)) {
                return bitmap_info_nbits(binfo);
            }
            word >>= 1;
            bit++;
        }
        return bit;
    }
    // Reset group_bit for next iterations
    group_bit = 0;
}
return bitmap_info_nbits(binfo);

